  'Battery & background activity': 'Akku ja taustatoiminta',
  'The open computer updates live. Less frequent checks of other computers reduce network activity. Connections pause while the app is in the background; notifications and Live Activities are managed in Notifications. Disabled widgets keep their last saved snapshot.':
    'Avoimen tietokoneen tiedot päivittyvät reaaliajassa. Muiden tietokoneiden harvemmat tarkistukset vähentävät verkkoliikennettä. Yhteydet keskeytetään sovelluksen ollessa taustalla; ilmoituksia ja Live Activities -toimintoja hallitaan kohdassa Ilmoitukset. Käytöstä poistetut widgetit säilyttävät viimeksi tallennetun tilannekuvansa.',
