  'This thread stays read-only. Retry the move, or cancel it. Cancel unlocks the thread only after {value0} confirms that it removed its copy. If {value1} already received the thread, cancel finishes the move instead.':
    'Tämä keskusteluketju pysyy vain luku -tilassa. Yritä siirtoa uudelleen tai peruuta se. Ketju avautuu muokattavaksi vasta, kun {value0} vahvistaa poistaneensa oman kopionsa. Jos {value1} on jo vastaanottanut ketjun, peruutus viimeistelee siirron.',
