  'Cancel move': 'Peruuta siirto',
  'Cancel copy': 'Peruuta kopiointi',
  'Move the full saved conversation, checklist, attachments and files. Provider sessions and credentials stay here. The destination thread uses that computer’s default harness, with no more access than this thread has. Nothing runs until you send the next message there. You can change its model after it opens. This thread stays here, read-only, for recovery.':
    'Siirrä koko tallennettu keskustelu, tarkistuslista, liitteet ja tiedostot. Palveluntarjoajien istunnot ja tunnistetiedot pysyvät täällä. Kohteen keskusteluketju käyttää kyseisen tietokoneen oletustyöympäristöä, eikä sillä ole enempää käyttöoikeuksia kuin tällä ketjulla. Mitään ei suoriteta ennen kuin lähetät siellä seuraavan viestin. Voit vaihtaa mallia, kun ketju on avattu. Tämä keskusteluketju pysyy täällä vain luku -tilassa palautusta varten.',
  'Copy files and local Git history. The source project and chats stay here. A new folder is created on the destination. Worktrees use its configured worktree directory.':
    'Kopioi tiedostot ja paikallinen Git-historia. Lähdeprojekti ja keskustelut pysyvät täällä. Kohteeseen luodaan uusi kansio. Työpuut käyttävät sille määritettyä työhakemistoa.',
