  'At this level: {value0}': 'Tällä tasolla: {value0}',
  'Project overrides Computer; Project on computer wins over both. The check marks the effective value for each computer, including later overrides.':
    'Projekti ohittaa Tietokoneen; tietokonekohtainen Projekti ohittaa molemmat. Valintamerkki osoittaa kunkin tietokoneen käyttöön tulevan arvon myöhemmät ohitukset mukaan lukien.',
  'The value above comes from the latest settings read. Source details below use saved snapshots.':
    'Yllä oleva arvo on peräisin viimeisimmästä asetusten luvusta. Alla olevat lähdetiedot perustuvat tallennettuihin tilannevedoksiin.',
