  ' · effective': ' · voimassa',
  ' · current draft': ' · nykyinen luonnos',
  'These levels keep their own value when {value0} changes. Open one to edit it, or reset them all to inherit again.':
    'Näillä tasoilla säilyy oma arvonsa, kun kohteen {value0} arvo muuttuu. Avaa taso muokataksesi sitä tai nollaa kaikki tasot, jotta ne perivät arvon uudelleen.',
  'Open {value0} settings for {value1}': 'Avaa kohteen {value0} asetukset: {value1}',
  'Resetting…': 'Nollataan…',
