  'Use inherited {value0}{value1}': 'Käytä perittyä {value0}{value1}',
  'Set up CuaDriver on this runtime host. CuaDriver owns OS permissions; Dovo connects agents through MCP.':
    'Määritä CuaDriver tällä runtime-isännällä. CuaDriver hallitsee käyttöjärjestelmän käyttöoikeuksia; Dovo yhdistää agentit MCP:n kautta.',
  'Host executable names or paths, without shell quoting. Agent overrides take precedence. New terminals use these shell settings.':
    'Isännän suoritettavien tiedostojen nimet tai polut ilman komentotulkin lainausmerkkejä. Agenttikohtaiset ohitukset ovat etusijalla. Uudet päätteet käyttävät näitä komentotulkin asetuksia.',
  'Loading {value0} settings…': 'Ladataan kohteen {value0} asetuksia…',
  'computer-use': 'computer-use',
  command: 'command',
  'Shell arguments (one per line)': 'Komentotulkin argumentit (yksi rivillä)',
  'Automatic shell: {value0}. Default: -l (login shell).':
    'Automaattinen komentotulkki: {value0}. Oletus: -l (kirjautumiskomentotulkki).',
  'Enable agent computer use on this computer':
    'Ota agentin tietokoneen käyttö käyttöön tässä tietokoneessa',
  'Grants writable agents access to this computer’s desktop. Read-only agents are excluded. The user and agents share the desktop and app state.':
    'Antaa kirjoitusoikeuksilla toimiville agenteille pääsyn tämän tietokoneen työpöytään. Vain luku -agentit eivät kuulu tähän. Käyttäjä ja agentit jakavat työpöydän ja sovellusten tilan.',
  'Leave Cua Driver empty to detect it on this computer’s PATH or in its standard installation folder. Changes apply to new agent turns.':
    'Jätä Cua Driver -kenttä tyhjäksi, jotta se etsitään tämän tietokoneen PATH-muuttujasta tai sen vakiotyyppisestä asennuskansiosta. Muutokset koskevat uusia agenttivuoroja.',
  '1. Install on this computer': '1. Asenna tähän tietokoneeseen',
  'Run the official installer on the runtime host, then refresh status. It downloads and installs CuaDriver; no Cua account is required.':
    'Suorita virallinen asennusohjelma runtime-isännällä ja päivitä sitten tila. Se lataa ja asentaa CuaDriverin; Cua-tiliä ei tarvita.',
  'Minimal Linux systems need libxi6 and at-spi2-core. GNOME needs Cua’s bundled WinRects helper; see the installation guide.':
    'Minimaalisissa Linux-järjestelmissä tarvitaan libxi6 ja at-spi2-core. GNOME tarvitsee Cuan mukana toimitettavan WinRects-apuohjelman; katso asennusopas.',
  'Install and set up Cua Driver': 'Asenna ja määritä Cua Driver',
  'Detect / check Cua Driver': 'Tunnista / tarkista Cua Driver',
  '2. Permissions & desktop access': '2. Käyttöoikeudet ja työpöydän käyttö',
  '3. Agent MCP, skills & hooks': '3. Agentin MCP, taidot ja koukut',
  '4. Computer History (optional preview)': '4. Computer History (valinnainen esikatselu)',
  'Grant macOS Accessibility and Screen Recording to CuaDriver and accept its relaunch. Test desktop access lists apps without changing them. Daemon controls affect active computer-use sessions.':
    'Anna CuaDriverille macOS:n Käyttöapu- ja Näytön tallennus -käyttöoikeudet ja hyväksy sen uudelleenkäynnistys. Työpöydän käyttöoikeuden testaaminen näyttää sovellukset muuttamatta niitä. Daemonin ohjaimet vaikuttavat aktiivisiin tietokoneen käyttöistuntoihin.',
  'Save the computer-use switch for automatic dovo_cua MCP on new writable turns. No manual MCP registration is needed. Install the optional official skill pack; installation links detected agents on this computer.':
    'Tallenna tietokoneen käytön kytkin, jotta dovo_cua MCP otetaan automaattisesti käyttöön uusilla kirjoitusoikeuksilla toimivilla vuoroilla. MCP:tä ei tarvitse rekisteröidä manuaalisesti. Asenna valinnainen virallinen taitopaketti; asennus linkittää tunnistetut agentit tähän tietokoneeseen.',
  'Opt-in, encrypted, metadata-only history. Enable may restart the daemon. Disable keeps recorded data; pause temporarily stops recording. Unsupported builds report an error. Data stays on the runtime host; View recent history retrieves up to 20 events here.':
    'Käyttöön otettava, salattu, vain metatietoja sisältävä historia. Käyttöönotto voi käynnistää daemonin uudelleen. Käytöstä poistaminen säilyttää tallennetut tiedot; tauko keskeyttää tallennuksen tilapäisesti. Tuetut versiot ilmoittavat virheestä. Tiedot pysyvät runtime-isännällä; Näytä viimeisin historia hakee tähän enintään 20 tapahtumaa.',
  'Delete recorded Computer History?': 'Poistetaanko tallennettu Computer History?',
  'Delete all recorded history and its encryption key on this computer. This cannot be undone.':
    'Poistaa kaiken tallennetun historian ja sen salausavaimen tältä tietokoneelta. Tätä ei voi kumota.',
