  'Dovo Connect: {value0}': 'Dovo Connect: {value0}',
  'Pair again': 'Muodosta pariliitos uudelleen',
  'Connection stages': 'Yhteyden muodostamisen vaiheet',
  'Start your computer': 'Käynnistä tietokone',
  'Open Dovo on your computer and keep it awake. In Settings → Devices & runtime, sign in and enable Dovo Connect. Sign in to the same account on your phone and choose Connect. No pairing code, VPN or local IP is needed for internet access.':
    'Avaa Dovo tietokoneellasi ja pidä se hereillä. Kirjaudu sisään kohdassa Settings → Devices & runtime ja ota Dovo Connect käyttöön. Kirjaudu puhelimellasi samalle tilille ja valitse Connect. Internetyhteys ei vaadi pariliitoskoodia, VPN:ää tai paikallista IP-osoitetta.',
  'Direct internet connection': 'Suora internetyhteys',
  'WebRTC + STUN connects your phone directly to the computer. Your content is end-to-end encrypted. Enabling Dovo Connect permits an encrypted relay fallback if a network blocks direct connections. The relay forwards encrypted traffic; it cannot read your content.':
    'WebRTC + STUN yhdistää puhelimesi suoraan tietokoneeseen. Sisältösi on salattu päästä päähän. Dovo Connectin käyttöönotto sallii salatun välityspalvelimen varayhteyden, jos verkko estää suorat yhteydet. Välityspalvelin välittää salattua liikennettä eikä voi lukea sisältöäsi.',
  'LAN / VPN connections': 'Lähiverkko-/VPN-yhteydet',
  'Pair LAN / VPN separately to prefer that connection when available. Copy the full Wi-Fi, Tailscale, NetBird, or HTTPS address shown on your computer, including its port. localhost and 0.0.0.0 are not addresses your phone can connect to.':
    'Muodosta lähiverkon/VPN:n kautta erillinen pariliitos, jos haluat käyttää sitä ensisijaisesti silloin, kun se on käytettävissä. Kopioi tietokoneella näkyvä Wi-Fi-, Tailscale-, NetBird- tai HTTPS-osoite kokonaisuudessaan portteineen. localhost ja 0.0.0.0 eivät ole osoitteita, joihin puhelimesi voi muodostaa yhteyden.',
  'Check your network': 'Tarkista verkkoyhteys',
  'Use the same Wi-Fi or connect both devices to your VPN. For Wi-Fi connections, allow Dovo access to your Local Network in iPhone Settings.':
    'Käytä samaa Wi-Fi-verkkoa tai yhdistä molemmat laitteet VPN-verkkoosi. Wi-Fi-yhteyttä varten salli iPhonen asetuksissa Dovon pääsy lähiverkkoon.',
  'Pairing codes expire after two minutes. CLI codes approve automatically; a code from the desktop may need approval there.':
    'Pariliitoskoodit vanhenevat kahden minuutin kuluttua. CLI-koodit hyväksytään automaattisesti; työpöytäsovelluksessa luotu koodi saattaa vaatia hyväksynnän siellä.',
  'Your pairing is saved. Try Reconnect before generating another code. If the address changed, choose Update connection address in this computer’s settings.':
    'Pariliitos on tallennettu. Kokeile ensin Yhdistä uudelleen -toimintoa, ennen kuin luot uuden koodin. Jos osoite muuttui, valitse tämän tietokoneen asetuksista Päivitä yhteyden osoite.',
